<template>
  <tr
    :class="{ 'project-row': true, 'clicked-row': isExpanded }"
    @click="handleRowClick"
  >
    <td>{{ project.date }}</td>
    <td class="name-cell">{{ project.name }}</td>
    <td>{{ project.type }}</td>
    <!-- <td>{{ project.technologies }}</td> -->
    <td>{{ project.description }}</td>
  </tr>

  <tr class="expandable-row" v-if="isExpanded" ref="expandableRow">
    <td :colspan="expandedColspan">
      <div class="expanded-content">
        <!-- First element (video if exists) -->
        <div v-if="project.video" class="video-container">
          <video
            autoplay
            muted
            loop
            playsinline
            preload="metadata"
            class="project-video"
          >
            <source :src="project.video.webm" type="video/webm" />
            <source :src="project.video.mp4" type="video/mp4" />
            <img :src="project.video.poster" alt="Video not supported" />
          </video>
        </div>

        <!-- First image if iframe does not exist -->
        <div v-else-if="project.images.length > 0" class="project-image">
          <img :src="project.images[0].src" :alt="project.images[0].alt" />
          <br />
          <div class="caption">{{ project.images[0].caption }}</div>
        </div>

        <!-- Project info (details and links) -->
        <div class="project-text">
          <b>DETAILS:</b>
          <br /><br />
          <div v-html="project.details"></div>
          <br /><br />
          <!-- UNCOMMENT TO TURN ON SEE MORE BUTTONS -->
          <!-- <router-link v-if="project.route" :to="project.route">
            <button class="view-project-button">See more</button>
          </router-link> -->
          <br /><br />
          <div v-for="(link, index) in project.links" :key="index">
            <a :href="link.url" target="_blank">{{ link.text }}</a>
            <br />
          </div>
        </div>

        <!-- Rest of the images -->
        <div
          v-for="(image, index) in project.images.slice(project.video ? 0 : 1)"
          :key="index"
          class="project-image"
        >
          <img :src="image.src" :alt="image.alt" />
          <br />
          <div class="caption">{{ image.caption }}</div>
        </div>
      </div>
    </td>
  </tr>
</template>

<script>
  import { visibleColumnCount } from '@/utils/visibleColumns.js';

  export default {
    name: 'Project',
    props: {
      project: {
        type: Object,
        required: true,
      },
      expandedProject: {
        type: String,
        required: false,
      },
    },
    computed: {
      isExpanded() {
        return this.expandedProject === this.project.name;
      },
      // Only the columns still on screen, so the expanded row can't add any.
      expandedColspan() {
        return visibleColumnCount.value;
      },
    },
    methods: {
      handleRowClick() {
        const newExpandedProject = this.isExpanded ? null : this.project.name;
        this.$emit('update:expandedProject', newExpandedProject);
      },
    },
  };
</script>

